-- Phase 6 is the sole allowed continuation after 20291217161000; forward-only, transactional, and safe for fresh installs.

CREATE TABLE public.festival_sponsorship_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_company_id uuid UNIQUE NOT NULL REFERENCES public.festival_companies(id) ON DELETE CASCADE,operations_plan_id uuid UNIQUE NOT NULL REFERENCES public.festival_operations_plans(id),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),sponsorship_target_minor bigint NOT NULL CHECK(sponsorship_target_minor>=0),minimum_cash_target_minor bigint NOT NULL CHECK(minimum_cash_target_minor>=0),maximum_in_kind_share_basis_points integer NOT NULL CHECK(maximum_in_kind_share_basis_points BETWEEN 0 AND 10000),minimum_player_company_share_basis_points integer NOT NULL CHECK(minimum_player_company_share_basis_points BETWEEN 0 AND 10000),application_mode text NOT NULL CHECK(application_mode IN('closed','invite_only','applications_only','hybrid')),public_applications_open_at timestamptz,public_applications_close_at timestamptz,status text NOT NULL DEFAULT 'not_started' CHECK(status IN('not_started','inventory_configured','applications_open','proposals_in_progress','contracts_in_progress','commercial_plan_complete','ready_for_final_readiness')),planning_version integer NOT NULL DEFAULT 1 CHECK(planning_version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,CHECK(public_applications_close_at IS NULL OR public_applications_open_at IS NULL OR public_applications_open_at<public_applications_close_at));
CREATE TABLE public.festival_sponsor_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,name text NOT NULL,minimum_festival_scale text,maximum_active_sponsors integer NOT NULL DEFAULT 1 CHECK(maximum_active_sponsors>0),default_exclusivity boolean NOT NULL DEFAULT false,minimum_contribution_minor bigint NOT NULL DEFAULT 0,recommended_contribution_minor bigint NOT NULL DEFAULT 0,available_inventory_types text[] NOT NULL DEFAULT '{}',reputation_requirement integer NOT NULL DEFAULT 0 CHECK(reputation_requirement BETWEEN 0 AND 100),industry_restrictions text[] NOT NULL DEFAULT '{}');
CREATE TABLE public.festival_sponsorship_inventory(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_sponsorship_plan_id uuid NOT NULL REFERENCES public.festival_sponsorship_plans(id) ON DELETE CASCADE,inventory_type text NOT NULL,name text NOT NULL,description text,quantity_total integer NOT NULL CHECK(quantity_total>0),quantity_reserved integer NOT NULL DEFAULT 0 CHECK(quantity_reserved>=0),quantity_contracted integer NOT NULL DEFAULT 0 CHECK(quantity_contracted>=0),minimum_package_tier text,minimum_contribution_minor bigint CHECK(minimum_contribution_minor>=0),exclusive boolean NOT NULL DEFAULT false,visibility_score integer NOT NULL CHECK(visibility_score BETWEEN 0 AND 100),status text NOT NULL DEFAULT 'available' CHECK(status IN('available','reserved','contracted','archived')),inventory_version integer NOT NULL DEFAULT 1,stage_id uuid REFERENCES public.festival_stages(id),ticket_product_id uuid REFERENCES public.festival_ticket_products(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(quantity_reserved+quantity_contracted<=quantity_total));
CREATE TABLE public.festival_sponsorship_packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_sponsorship_plan_id uuid NOT NULL REFERENCES public.festival_sponsorship_plans(id) ON DELETE CASCADE,name text NOT NULL,tier text NOT NULL CHECK(tier IN('title','platinum','gold','silver','bronze','community','in_kind','media')),description text,minimum_cash_minor bigint NOT NULL CHECK(minimum_cash_minor>=0),minimum_in_kind_minor bigint NOT NULL CHECK(minimum_in_kind_minor>=0),maximum_in_kind_share_basis_points integer NOT NULL CHECK(maximum_in_kind_share_basis_points BETWEEN 0 AND 10000),exclusive_category boolean NOT NULL DEFAULT false,maximum_sponsors integer NOT NULL CHECK(maximum_sponsors>0),target_industries text[] NOT NULL DEFAULT '{}',excluded_industries text[] NOT NULL DEFAULT '{}',target_company_quality integer CHECK(target_company_quality BETWEEN 0 AND 100),target_company_reputation integer CHECK(target_company_reputation BETWEEN 0 AND 100),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','archived')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_sponsorship_package_inventory(package_id uuid NOT NULL REFERENCES public.festival_sponsorship_packages(id) ON DELETE CASCADE,inventory_id uuid NOT NULL REFERENCES public.festival_sponsorship_inventory(id) ON DELETE CASCADE,quantity integer NOT NULL CHECK(quantity>0),required boolean NOT NULL DEFAULT true,PRIMARY KEY(package_id,inventory_id));
CREATE TABLE public.festival_sponsor_prospects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_sponsorship_plan_id uuid NOT NULL REFERENCES public.festival_sponsorship_plans(id) ON DELETE CASCADE,sponsor_source text NOT NULL CHECK(sponsor_source IN('player_company','npc_company','admin_sponsor')),company_id uuid REFERENCES public.companies(id),npc_sponsor_id uuid,admin_sponsor_id uuid,category_id uuid REFERENCES public.festival_sponsor_categories(id),compatibility_score integer NOT NULL CHECK(compatibility_score BETWEEN 0 AND 100),audience_fit_score integer NOT NULL CHECK(audience_fit_score BETWEEN 0 AND 100),genre_fit_score integer NOT NULL CHECK(genre_fit_score BETWEEN 0 AND 100),festival_fit_score integer NOT NULL CHECK(festival_fit_score BETWEEN 0 AND 100),reputation_fit_score integer NOT NULL CHECK(reputation_fit_score BETWEEN 0 AND 100),commercial_capacity_score integer NOT NULL CHECK(commercial_capacity_score BETWEEN 0 AND 100),community_value_score integer NOT NULL CHECK(community_value_score BETWEEN 0 AND 100),relationship_score integer NOT NULL CHECK(relationship_score BETWEEN 0 AND 100),risk_score integer NOT NULL CHECK(risk_score BETWEEN 0 AND 100),risk_flags text[] NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(company_id,npc_sponsor_id,admin_sponsor_id)=1));
CREATE TABLE public.festival_sponsor_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_sponsorship_plan_id uuid NOT NULL REFERENCES public.festival_sponsorship_plans(id) ON DELETE CASCADE,package_id uuid REFERENCES public.festival_sponsorship_packages(id),company_id uuid NOT NULL REFERENCES public.companies(id),submitted_by_profile_id uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','under_review','shortlisted','proposal_pending','rejected','withdrawn','expired')),proposed_cash_minor bigint NOT NULL CHECK(proposed_cash_minor>=0),proposed_in_kind_minor bigint NOT NULL CHECK(proposed_in_kind_minor>=0),proposed_in_kind_items jsonb NOT NULL DEFAULT '[]',requested_inventory_ids uuid[] NOT NULL DEFAULT '{}',message text,company_quality_snapshot integer NOT NULL,company_reputation_snapshot integer NOT NULL,compatibility_snapshot jsonb NOT NULL,submitted_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,withdrawn_at timestamptz,application_version integer NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX festival_sponsor_application_active ON public.festival_sponsor_applications(festival_sponsorship_plan_id,company_id) WHERE status IN('submitted','under_review','shortlisted','proposal_pending');
CREATE TABLE public.festival_sponsor_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_sponsorship_plan_id uuid NOT NULL REFERENCES public.festival_sponsorship_plans(id) ON DELETE CASCADE,package_id uuid REFERENCES public.festival_sponsorship_packages(id),company_id uuid REFERENCES public.companies(id),npc_sponsor_id uuid,admin_sponsor_id uuid,invited_by_profile_id uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','sent','viewed','interested','declined','expired','converted_to_proposal','withdrawn')),suggested_cash_minor bigint CHECK(suggested_cash_minor>=0),suggested_in_kind_minor bigint CHECK(suggested_in_kind_minor>=0),suggested_inventory_ids uuid[] NOT NULL DEFAULT '{}',message text,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),responded_at timestamptz,invitation_version integer NOT NULL DEFAULT 1,CHECK(num_nonnulls(company_id,npc_sponsor_id,admin_sponsor_id)=1));
CREATE TABLE public.festival_sponsor_proposals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_sponsorship_plan_id uuid NOT NULL REFERENCES public.festival_sponsorship_plans(id) ON DELETE CASCADE,application_id uuid REFERENCES public.festival_sponsor_applications(id),invitation_id uuid REFERENCES public.festival_sponsor_invitations(id),sponsor_source text NOT NULL CHECK(sponsor_source IN('player_company','npc_company','admin_sponsor')),company_id uuid REFERENCES public.companies(id),npc_sponsor_id uuid,admin_sponsor_id uuid,package_id uuid NOT NULL REFERENCES public.festival_sponsorship_packages(id),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','sent','countered','accepted','declined','expired','withdrawn','superseded')),cash_contribution_minor bigint NOT NULL CHECK(cash_contribution_minor>=0),in_kind_contribution_minor bigint NOT NULL CHECK(in_kind_contribution_minor>=0),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),exclusivity_category text,exclusivity_scope text CHECK(exclusivity_scope IS NULL OR exclusivity_scope IN('industry','site','stage','package','naming_right','product_category')),starts_at timestamptz,ends_at timestamptz,response_deadline timestamptz,proposal_version integer NOT NULL DEFAULT 1,current_revision_id uuid,created_by_profile_id uuid REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),accepted_at timestamptz,declined_at timestamptz,withdrawn_at timestamptz,CHECK(num_nonnulls(company_id,npc_sponsor_id,admin_sponsor_id)=1));
CREATE TABLE public.festival_sponsor_proposal_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),proposal_id uuid NOT NULL REFERENCES public.festival_sponsor_proposals(id) ON DELETE CASCADE,proposal_version integer NOT NULL,proposed_by_party text NOT NULL CHECK(proposed_by_party IN('festival','sponsor','system','admin')),proposed_by_profile_id uuid REFERENCES public.profiles(id),cash_contribution_minor bigint NOT NULL CHECK(cash_contribution_minor>=0),in_kind_contribution_minor bigint NOT NULL CHECK(in_kind_contribution_minor>=0),inventory_snapshot jsonb NOT NULL,deliverables_snapshot jsonb NOT NULL,exclusivity_snapshot jsonb,terms_snapshot jsonb NOT NULL,message text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(proposal_id,proposal_version));
ALTER TABLE public.festival_sponsor_proposals ADD CONSTRAINT festival_sponsor_current_revision_fk FOREIGN KEY(current_revision_id) REFERENCES public.festival_sponsor_proposal_revisions(id);
CREATE TABLE public.festival_sponsor_contracts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_sponsorship_plan_id uuid NOT NULL REFERENCES public.festival_sponsorship_plans(id),accepted_proposal_id uuid UNIQUE NOT NULL REFERENCES public.festival_sponsor_proposals(id),sponsor_source text NOT NULL,company_id uuid REFERENCES public.companies(id),npc_sponsor_id uuid,admin_sponsor_id uuid,package_id uuid NOT NULL REFERENCES public.festival_sponsorship_packages(id),status text NOT NULL DEFAULT 'committed' CHECK(status IN('committed','awaiting_activation','active','fulfilled','cancelled','sponsor_defaulted','festival_cancelled')),cash_contribution_minor bigint NOT NULL CHECK(cash_contribution_minor>=0),in_kind_contribution_minor bigint NOT NULL CHECK(in_kind_contribution_minor>=0),total_contribution_minor bigint NOT NULL CHECK(total_contribution_minor=cash_contribution_minor+in_kind_contribution_minor),currency_code text NOT NULL,terms_snapshot jsonb NOT NULL,exclusivity_snapshot jsonb,contract_version integer NOT NULL DEFAULT 1,confirmed_at timestamptz NOT NULL DEFAULT now(),cancelled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(company_id,npc_sponsor_id,admin_sponsor_id)=1));
CREATE TABLE public.festival_sponsor_contributions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sponsor_contract_id uuid NOT NULL REFERENCES public.festival_sponsor_contracts(id) ON DELETE CASCADE,contribution_type text NOT NULL CHECK(contribution_type IN('cash','equipment','services','products','transport','accommodation','media','advertising','staffing','hospitality','other_in_kind')),category text,description text,quantity integer CHECK(quantity>0),unit_value_minor bigint CHECK(unit_value_minor>=0),total_value_minor bigint NOT NULL CHECK(total_value_minor>=0),currency_code text NOT NULL,delivery_start timestamptz,delivery_end timestamptz,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','committed','cancelled')),supplier_requirement_id uuid REFERENCES public.festival_supplier_requirements(id),coverage_mode text CHECK(coverage_mode IS NULL OR coverage_mode IN('additional_capacity','replace_uncovered','replace_planned_contract','none')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_branding_placements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sponsor_contract_id uuid NOT NULL REFERENCES public.festival_sponsor_contracts(id) ON DELETE CASCADE,inventory_id uuid NOT NULL REFERENCES public.festival_sponsorship_inventory(id),placement_type text NOT NULL,stage_id uuid REFERENCES public.festival_stages(id),ticket_product_id uuid REFERENCES public.festival_ticket_products(id),location_reference text,quantity integer NOT NULL CHECK(quantity>0),exclusivity_key text,visibility_score integer NOT NULL CHECK(visibility_score BETWEEN 0 AND 100),status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','contracted','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(sponsor_contract_id,inventory_id));
CREATE TABLE public.festival_sponsor_deliverables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sponsor_contract_id uuid NOT NULL REFERENCES public.festival_sponsor_contracts(id) ON DELETE CASCADE,deliverable_type text NOT NULL,description text,quantity integer NOT NULL CHECK(quantity>0),due_at timestamptz,verification_method text,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','contracted','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_financial_receivables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id),sponsor_contract_id uuid NOT NULL REFERENCES public.festival_sponsor_contracts(id),source_type text NOT NULL CHECK(source_type IN('sponsor_contract_cash','sponsor_contract_in_kind')),amount_minor bigint NOT NULL CHECK(amount_minor>=0),currency_code text NOT NULL,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','cancelled','settled')),created_at timestamptz NOT NULL DEFAULT now(),cancelled_at timestamptz,UNIQUE(sponsor_contract_id,source_type));
CREATE TABLE public.festival_sponsor_company_commitments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),sponsor_contract_id uuid UNIQUE NOT NULL REFERENCES public.festival_sponsor_contracts(id),amount_minor bigint NOT NULL CHECK(amount_minor>=0),currency_code text NOT NULL,status text NOT NULL DEFAULT 'reserved' CHECK(status IN('reserved','released','settled')),created_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz);
CREATE TABLE public.festival_sponsor_feedback(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_sponsorship_plan_id uuid NOT NULL REFERENCES public.festival_sponsorship_plans(id),company_id uuid REFERENCES public.companies(id),npc_sponsor_id uuid,admin_sponsor_id uuid,stage text NOT NULL,rating integer CHECK(rating BETWEEN 1 AND 5),reason_codes text[] NOT NULL DEFAULT '{}',message_key text NOT NULL,safe_metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(company_id,npc_sponsor_id,admin_sponsor_id)=1));
CREATE TABLE public.festival_sponsorship_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id),actor_profile_id uuid NOT NULL REFERENCES public.profiles(id),action text NOT NULL,target_id uuid,idempotency_key uuid NOT NULL,payload_hash text NOT NULL,status text NOT NULL DEFAULT 'processing',result jsonb,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(actor_profile_id,action,target_id,idempotency_key));
CREATE TABLE public.festival_sponsorship_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id),actor_profile_id uuid REFERENCES public.profiles(id),entity_type text NOT NULL,entity_id uuid NOT NULL,event_type text NOT NULL,previous_state text,new_state text,version integer NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',request_id uuid REFERENCES public.festival_sponsorship_requests(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,event_type));
