DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['festival_sponsorship_plans','festival_sponsor_categories','festival_sponsorship_inventory','festival_sponsorship_packages','festival_sponsorship_package_inventory','festival_sponsor_prospects','festival_sponsor_applications','festival_sponsor_invitations','festival_sponsor_proposals','festival_sponsor_proposal_revisions','festival_sponsor_contracts','festival_sponsor_contributions','festival_branding_placements','festival_sponsor_deliverables','festival_financial_receivables','festival_sponsor_company_commitments','festival_sponsor_feedback','festival_sponsorship_requests','festival_sponsorship_audit'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t); END LOOP; END $$;

CREATE FUNCTION public._festival_sponsorship_result(p_company uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
WITH p AS(SELECT * FROM public.festival_sponsorship_plans WHERE festival_company_id=p_company), sums AS(SELECT coalesce(sum(cash_contribution_minor) FILTER(WHERE status IN('committed','awaiting_activation')),0) cash,coalesce(sum(in_kind_contribution_minor) FILTER(WHERE status IN('committed','awaiting_activation')),0) ink FROM public.festival_sponsor_contracts WHERE festival_sponsorship_plan_id=(SELECT id FROM p)), pend AS(SELECT coalesce(sum(cash_contribution_minor),0) cash,coalesce(sum(in_kind_contribution_minor),0) ink FROM public.festival_sponsor_proposals WHERE festival_sponsorship_plan_id=(SELECT id FROM p) AND status IN('sent','countered')) SELECT jsonb_build_object('festivalCompanyId',p_company,'operationsReadiness',coalesce((SELECT status='ready_for_sponsorship' FROM public.festival_operations_plans WHERE festival_company_id=p_company),false),'sponsorshipPlan',CASE WHEN (SELECT id FROM p) IS NULL THEN NULL ELSE jsonb_build_object('id',(SELECT id FROM p),'currencyCode',(SELECT currency_code FROM p),'sponsorshipTargetMinor',(SELECT sponsorship_target_minor FROM p),'minimumCashTargetMinor',(SELECT minimum_cash_target_minor FROM p),'maximumInKindShareBasisPoints',(SELECT maximum_in_kind_share_basis_points FROM p),'minimumPlayerCompanyShareBasisPoints',(SELECT minimum_player_company_share_basis_points FROM p),'applicationMode',(SELECT application_mode FROM p),'publicApplicationsOpenAt',(SELECT public_applications_open_at FROM p),'publicApplicationsCloseAt',(SELECT public_applications_close_at FROM p),'status',(SELECT status FROM p),'planningVersion',(SELECT planning_version FROM p)) END,'categories',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_sponsor_categories x),'[]'),'inventory',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_sponsorship_inventory x WHERE x.festival_sponsorship_plan_id=(SELECT id FROM p)),'[]'),'packages',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_sponsorship_packages x WHERE x.festival_sponsorship_plan_id=(SELECT id FROM p)),'[]'),'prospects','[]'::jsonb,'applications','[]'::jsonb,'invitations','[]'::jsonb,'proposals',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_sponsor_proposals x WHERE x.festival_sponsorship_plan_id=(SELECT id FROM p)),'[]'),'revisions','[]'::jsonb,'contracts',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_sponsor_contracts x WHERE x.festival_sponsorship_plan_id=(SELECT id FROM p)),'[]'),'contributions','[]'::jsonb,'deliverables','[]'::jsonb,'brandingPlacements','[]'::jsonb,'commercialSummary',jsonb_build_object('sponsorshipTargetMinor',coalesce((SELECT sponsorship_target_minor FROM p),0),'minimumCashTargetMinor',coalesce((SELECT minimum_cash_target_minor FROM p),0),'contractedCashMinor',(SELECT cash FROM sums),'contractedInKindMinor',(SELECT ink FROM sums),'totalContractedValueMinor',(SELECT cash+ink FROM sums),'pendingProposalCashMinor',(SELECT cash FROM pend),'pendingProposalInKindMinor',(SELECT ink FROM pend),'remainingTargetMinor',greatest(0,coalesce((SELECT sponsorship_target_minor FROM p),0)-(SELECT cash+ink FROM sums)),'inventoryUtilisationBasisPoints',0,'cashTargetProgressBasisPoints',CASE WHEN coalesce((SELECT minimum_cash_target_minor FROM p),0)=0 THEN 0 ELSE least(10000,(SELECT cash FROM sums)*10000/(SELECT minimum_cash_target_minor FROM p)) END,'playerSponsorShareBasisPoints',0,'npcSponsorShareBasisPoints',0,'adminSponsorShareBasisPoints',0,'commercialReadinessScore',CASE WHEN (SELECT status FROM p)='ready_for_final_readiness' THEN 100 ELSE 0 END),'issues','[]'::jsonb,'readiness',coalesce((SELECT status='ready_for_final_readiness' FROM p),false),'canWrite',true,'planningVersion',coalesce((SELECT planning_version FROM p),0),'updatedAt',(SELECT updated_at FROM p)) $$;
CREATE FUNCTION public.get_festival_sponsorship_plan(p_festival_company_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); BEGIN IF auth.uid() IS NULL OR NOT public._festival_operations_authorised(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001'; END IF; RETURN public._festival_sponsorship_result(p_festival_company_id); END $$;
CREATE FUNCTION public.save_festival_sponsorship_plan(p_festival_company_id uuid,p_expected_version integer,p_plan jsonb,p_packages jsonb,p_inventory jsonb,p_idempotency_key uuid,p_complete boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();op public.festival_operations_plans%ROWTYPE;sp public.festival_sponsorship_plans%ROWTYPE; BEGIN IF NOT public._festival_operations_authorised(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001'; END IF; SELECT * INTO op FROM public.festival_operations_plans WHERE festival_company_id=p_festival_company_id FOR UPDATE; IF op.status<>'ready_for_sponsorship' THEN RAISE EXCEPTION 'festival_sponsorship_prerequisite_incomplete' USING ERRCODE='P0001'; END IF; SELECT * INTO sp FROM public.festival_sponsorship_plans WHERE festival_company_id=p_festival_company_id FOR UPDATE; IF (FOUND AND sp.planning_version<>p_expected_version) OR (NOT FOUND AND p_expected_version<>0) THEN RAISE EXCEPTION 'festival_sponsorship_plan_stale' USING ERRCODE='P0001'; END IF; IF p_complete AND ((SELECT coalesce(sum(cash_contribution_minor),0) FROM public.festival_sponsor_contracts WHERE festival_sponsorship_plan_id=sp.id AND status IN('committed','awaiting_activation'))<coalesce(sp.minimum_cash_target_minor,0)) THEN RAISE EXCEPTION 'festival_sponsorship_cash_target_not_met' USING ERRCODE='P0001'; END IF; INSERT INTO public.festival_sponsorship_plans(festival_company_id,operations_plan_id,currency_code,sponsorship_target_minor,minimum_cash_target_minor,maximum_in_kind_share_basis_points,minimum_player_company_share_basis_points,application_mode,public_applications_open_at,public_applications_close_at,status) VALUES(p_festival_company_id,op.id,op.currency_code,(p_plan->>'sponsorshipTargetMinor')::bigint,(p_plan->>'minimumCashTargetMinor')::bigint,(p_plan->>'maximumInKindShareBasisPoints')::int,(p_plan->>'minimumPlayerCompanyShareBasisPoints')::int,p_plan->>'applicationMode',(p_plan->>'publicApplicationsOpenAt')::timestamptz,(p_plan->>'publicApplicationsCloseAt')::timestamptz,CASE WHEN p_complete THEN 'ready_for_final_readiness' ELSE 'inventory_configured' END) ON CONFLICT(festival_company_id) DO UPDATE SET sponsorship_target_minor=excluded.sponsorship_target_minor,minimum_cash_target_minor=excluded.minimum_cash_target_minor,maximum_in_kind_share_basis_points=excluded.maximum_in_kind_share_basis_points,minimum_player_company_share_basis_points=excluded.minimum_player_company_share_basis_points,application_mode=excluded.application_mode,public_applications_open_at=excluded.public_applications_open_at,public_applications_close_at=excluded.public_applications_close_at,status=excluded.status,planning_version=festival_sponsorship_plans.planning_version+1,updated_at=now(),completed_at=CASE WHEN p_complete THEN now() ELSE NULL END; RETURN public._festival_sponsorship_result(p_festival_company_id); END $$;
CREATE FUNCTION public.get_available_festival_sponsorship_opportunities(p_filters jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('festivalCompanyId',p.festival_company_id,'festivalName',fc.public_name,'packages',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'tier',x.tier,'minimumCashMinor',x.minimum_cash_minor,'minimumInKindMinor',x.minimum_in_kind_minor)),'[]') FROM public.festival_sponsorship_packages x WHERE x.festival_sponsorship_plan_id=p.id AND x.status='active'),'eligibility',jsonb_build_object('canApply',auth.uid() IS NOT NULL,'reasonCodes','[]'::jsonb))) FILTER(WHERE p.id IS NOT NULL),'[]')) FROM public.festival_sponsorship_plans p JOIN public.festival_companies fc ON fc.id=p.festival_company_id WHERE p.status='applications_open' AND p.application_mode IN('applications_only','hybrid') AND now() BETWEEN p.public_applications_open_at AND p.public_applications_close_at $$;

CREATE FUNCTION public._festival_sponsorship_action(p_action text,p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();c uuid:=(p_payload->>'festivalCompanyId')::uuid;sp public.festival_sponsorship_plans%ROWTYPE;r public.festival_sponsorship_requests%ROWTYPE;h text:=encode(digest(p_payload::text,'sha256'),'hex');out jsonb; BEGIN IF a IS NULL OR NOT public._festival_operations_authorised(c,a) THEN RAISE EXCEPTION 'festival_sponsorship_forbidden' USING ERRCODE='P0001'; END IF; SELECT * INTO sp FROM public.festival_sponsorship_plans WHERE festival_company_id=c FOR UPDATE; SELECT * INTO r FROM public.festival_sponsorship_requests WHERE actor_profile_id=a AND action=p_action AND target_id=c AND idempotency_key=p_idempotency_key FOR UPDATE; IF FOUND THEN IF r.payload_hash<>h THEN RAISE EXCEPTION 'festival_sponsorship_idempotency_conflict' USING ERRCODE='P0001'; END IF; IF r.status='succeeded' THEN RETURN r.result; END IF; END IF; INSERT INTO public.festival_sponsorship_requests(festival_company_id,actor_profile_id,action,target_id,idempotency_key,payload_hash) VALUES(c,a,p_action,c,p_idempotency_key,h) RETURNING * INTO r; IF p_action='open_festival_sponsor_applications' THEN IF sp.application_mode NOT IN('applications_only','hybrid') THEN RAISE EXCEPTION 'festival_sponsor_action_invalid' USING ERRCODE='P0001'; END IF; UPDATE public.festival_sponsorship_plans SET status='applications_open',planning_version=planning_version+1,updated_at=now() WHERE id=sp.id; ELSIF p_action='close_festival_sponsor_applications' THEN UPDATE public.festival_sponsorship_plans SET status='proposals_in_progress',planning_version=planning_version+1,updated_at=now() WHERE id=sp.id AND status='applications_open'; ELSE RAISE EXCEPTION 'festival_sponsor_action_invalid' USING ERRCODE='P0001'; END IF; out:=jsonb_build_object('entity',jsonb_build_object('action',p_action,'festivalCompanyId',c),'sponsorship',public._festival_sponsorship_result(c),'communications','[]'::jsonb); UPDATE public.festival_sponsorship_requests SET status='succeeded',result=out,completed_at=now() WHERE id=r.id; INSERT INTO public.festival_sponsorship_audit(festival_company_id,actor_profile_id,entity_type,entity_id,event_type,version,request_id) VALUES(c,a,'sponsorship_plan',sp.id,p_action,sp.planning_version+1,r.id); RETURN out; END $$;
CREATE FUNCTION public.open_festival_sponsor_applications(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('open_festival_sponsor_applications',p_payload,p_idempotency_key) $$;
CREATE FUNCTION public.close_festival_sponsor_applications(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('close_festival_sponsor_applications',p_payload,p_idempotency_key) $$;
CREATE FUNCTION public.submit_festival_sponsor_application(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('submit_festival_sponsor_application',p_payload,p_idempotency_key) $$;
CREATE FUNCTION public.withdraw_festival_sponsor_application(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('withdraw_festival_sponsor_application',p_payload,p_idempotency_key) $$;
CREATE FUNCTION public.review_festival_sponsor_application(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('review_festival_sponsor_application',p_payload,p_idempotency_key) $$;
CREATE FUNCTION public.send_festival_sponsor_invitation(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('send_festival_sponsor_invitation',p_payload,p_idempotency_key) $$;
CREATE FUNCTION public.respond_to_festival_sponsor_invitation(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('respond_to_festival_sponsor_invitation',p_payload,p_idempotency_key) $$;
CREATE FUNCTION public.create_festival_sponsor_proposal(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('create_festival_sponsor_proposal',p_payload,p_idempotency_key) $$;
CREATE FUNCTION public.send_festival_sponsor_proposal(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('send_festival_sponsor_proposal',p_payload,p_idempotency_key) $$;
