CREATE FUNCTION public.cancel_festival_sponsor_contract(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('cancel_festival_sponsor_contract',p_payload,p_idempotency_key) $$;
CREATE FUNCTION public.refresh_festival_npc_sponsor_prospects(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('refresh_festival_npc_sponsor_prospects',p_payload,p_idempotency_key) $$;
CREATE FUNCTION public.search_festival_sponsor_prospects(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_sponsorship_action('search_festival_sponsor_prospects',p_payload,p_idempotency_key) $$;
REVOKE ALL ON FUNCTION public._festival_sponsorship_action(text,jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.open_festival_sponsor_applications(jsonb,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.close_festival_sponsor_applications(jsonb,uuid) TO authenticated;
