GRANT EXECUTE ON FUNCTION public.get_festival_sponsorship_plan(uuid),public.save_festival_sponsorship_plan(uuid,integer,jsonb,jsonb,jsonb,uuid,boolean),public.get_available_festival_sponsorship_opportunities(jsonb) TO authenticated;
